// 授業ライブ字幕（日本語・English・中文） v3.1 — served at /subtitles/class/
export default "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>授業ライブ字幕｜日本語・English・中文</title>\n<style>\n:root{--bg:#f4f1ea;--card:#fff;--ink:#1d1d1f;--sub:#6b6b70;--line:#ddd6c8;--acc:#9b2c2c;--ok:#2f6f4f;--warn:#a15c00}\n*{box-sizing:border-box}\nbody{margin:0;font-family:\"Yu Gothic UI\",\"Hiragino Sans\",\"Noto Sans JP\",\"Microsoft JhengHei\",sans-serif;background:var(--bg);color:var(--ink);line-height:1.5}\nheader{display:flex;align-items:center;gap:12px;padding:12px 20px;background:#1d1d1f;color:#fff}\nheader h1{font-size:18px;margin:0;font-weight:700}\nheader .ver{font-size:12px;opacity:.7}\nheader .status{margin-left:auto;font-size:14px;display:flex;align-items:center;gap:8px}\n.dot{width:10px;height:10px;border-radius:50%;background:#777}\n.dot.on{background:#e53e3e;box-shadow:0 0 0 4px rgba(229,62,62,.3);animation:p 1.4s infinite}\n@keyframes p{50%{box-shadow:0 0 0 8px rgba(229,62,62,.05)}}\nmain{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:16px;padding:16px 20px;max-width:1500px;margin:0 auto}\n@media(max-width:1000px){main{grid-template-columns:1fr}}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin-bottom:16px}\n.card h2{font-size:15px;margin:0 0 10px;display:flex;align-items:center;gap:8px}\n.card h2 small{font-weight:400;color:var(--sub);font-size:12px}\nbutton{font:inherit;border:1px solid var(--line);background:#fff;border-radius:8px;padding:8px 14px;cursor:pointer}\nbutton:hover{border-color:#999}\nbutton.primary{background:var(--acc);border-color:var(--acc);color:#fff;font-weight:700}\nbutton.primary.stop{background:#333;border-color:#333}\nbutton:disabled{opacity:.5;cursor:default}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.speakers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.speakers button{padding:14px 8px;font-size:17px;font-weight:700;border-width:2px}\n.speakers button small{display:block;font-size:11px;font-weight:400;color:var(--sub)}\n.speakers button.active{border-color:var(--acc);background:#fbeeee;color:var(--acc)}\n.big{font-size:17px;padding:12px 22px}\n#stage{background:#000;color:#fff;border-radius:10px;height:420px;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:18px 26px;position:relative}\n#stage:fullscreen{border-radius:0;height:100vh;padding:4vh 5vw}\n.sub-row{margin-top:.55em}\n.sub-line{display:flex;gap:.45em;align-items:baseline;line-height:1.3;word-break:break-word}\n.sub-line .tag{font-size:.42em;border:1px solid currentColor;border-radius:.3em;padding:0 .35em;opacity:.75;flex:none;transform:translateY(-.25em);font-weight:700}\n.sub-line.wait{opacity:.45}\n.sub-line.interim{opacity:.55}\n.sub-row.old{opacity:.55}\n.blank-note{position:absolute;inset:0;display:none;align-items:center;justify-content:center;color:#555;font-size:14px}\n#stage.blank .sub-row{visibility:hidden}\n#stage.blank .blank-note{display:flex}\nlabel{font-size:13px}\n.grid2{display:grid;grid-template-columns:auto 1fr;gap:6px 10px;align-items:center;font-size:13px}\nselect,input[type=number],input[type=text]{font:inherit;font-size:13px;padding:4px 6px;border:1px solid var(--line);border-radius:6px}\ntextarea{width:100%;font:13px/1.5 Consolas,\"Yu Gothic UI\",monospace;border:1px solid var(--line);border-radius:6px;padding:8px;resize:vertical}\n.msg{font-size:13px;color:var(--warn);min-height:1.2em;margin-top:8px;white-space:pre-wrap}\n.hint{font-size:12px;color:var(--sub)}\n.tr-status{font-size:12px;display:grid;grid-template-columns:auto 1fr;gap:2px 10px;margin-top:8px}\n.tr-status .ok{color:var(--ok)} .tr-status .ng{color:var(--acc)} .tr-status .dl{color:var(--warn)}\n#raw{font-size:14px;min-height:2.6em;background:#faf8f3;border-radius:6px;padding:8px;color:#444}\n#log{max-height:320px;overflow:auto;font-size:13px}\n#log .item{border-bottom:1px solid #eee;padding:6px 0}\n#log .item .t{color:var(--sub);font-size:11px}\n#log .item div[lang]{margin-left:8px}\nkbd{font:11px Consolas,monospace;border:1px solid #bbb;border-bottom-width:2px;border-radius:4px;padding:0 4px;background:#fafafa}\ndetails summary{cursor:pointer;font-size:14px;font-weight:700}\n.colors{display:flex;gap:12px;flex-wrap:wrap;font-size:13px}\n.colors input{width:36px;height:24px;padding:0;border:none;vertical-align:middle}\n.drop{border:2px dashed var(--line);border-radius:10px;padding:16px;text-align:center;background:#fcfbf8;font-size:14px}\n.drop.over{border-color:var(--acc);background:#fbeeee}\n.drop button{padding:2px 8px;font-size:12px}\n.howto{background:#fbf8f1;border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:0 0 8px;font-size:14px;line-height:1.7}\n.howto .bad{color:var(--acc);text-decoration:line-through}\n.howto .small{font-size:12px;color:var(--sub)}\n.chips{display:flex;flex-wrap:wrap;gap:4px;align-items:center;min-width:150px}\n.chip{display:inline-flex;align-items:center;gap:2px;background:#fdecec;border:1px solid #f0c9c9;border-radius:999px;padding:1px 4px 1px 9px;font-size:13px;white-space:nowrap}\n.chip.off{background:#eee;border-color:#ddd;color:#999;text-decoration:line-through}\n.chip button{border:none;background:none;color:#a33;font-size:13px;padding:0 4px;cursor:pointer;line-height:1}\n.chips .add{border:1px dashed #bbb;background:#fff;border-radius:999px;font-size:12px;padding:1px 9px;color:#666}\n.tablewrap{max-height:460px;overflow:auto;border:1px solid var(--line);border-radius:8px}\n#glossTable{border-collapse:collapse;width:100%;font-size:13px}\n#glossTable th{position:sticky;top:0;background:#f1ede4;font-weight:700;text-align:left;padding:6px;white-space:nowrap;z-index:1}\n#glossTable td{border-top:1px solid #eee;padding:3px 4px}\n#glossTable td input[type=text]{width:100%;min-width:70px;border:1px solid transparent;background:transparent;padding:3px 4px}\n#glossTable td input[type=text]:focus{border-color:#bbb;background:#fff}\n#glossTable tr.off td{opacity:.45}\n#glossTable td.n{color:var(--sub);text-align:right;padding-right:8px}\n#glossTable td button{padding:0 6px;font-size:12px;border:none;color:var(--sub)}\n#glossChip{font-size:12px;color:var(--sub);margin-left:auto}\n#log .fix{color:var(--ok);font-size:11px;margin-left:8px}\n.sub-line .fixed{border-bottom:2px solid rgba(255,255,255,.35)}\n</style>\n</head>\n<body>\n<header>\n  <h1>授業ライブ字幕 <span style=\"font-weight:400\">日本語・English・中文</span></h1>\n  <span class=\"ver\">v3.1</span>\n  <a href=\"/subtitles/m/\" style=\"color:#ccc;font-size:12px;margin-left:8px\">スマホ版</a>\n  <div class=\"status\"><span class=\"dot\" id=\"dot\"></span><span id=\"statusText\">停止中</span></div>\n</header>\n\n<main>\n<section>\n  <div class=\"card\">\n    <h2>話す人の言語 <small>押すと切り替わります（キー <kbd>1</kbd><kbd>2</kbd><kbd>3</kbd>）</small><a href=\"#glossCard\" id=\"glossChip\"></a></h2>\n    <div class=\"speakers\" id=\"speakers\">\n      <button data-lang=\"ja\">日本語<small>→ English・中文</small></button>\n      <button data-lang=\"en\">English<small>→ 日本語・中文</small></button>\n      <button data-lang=\"zh\">中文（台灣）<small>→ 日本語・English</small></button>\n    </div>\n    <div class=\"row\" style=\"margin-top:12px\">\n      <button class=\"primary big\" id=\"micBtn\">🎤 マイク開始</button>\n      <button id=\"projBtn\">🖥 プロジェクター用の画面</button>\n      <button id=\"fsBtn\">全画面 <kbd>F</kbd></button>\n      <button id=\"blankBtn\">字幕を消す <kbd>B</kbd></button>\n      <button id=\"clearBtn\">画面をクリア</button>\n    </div>\n    <div class=\"msg\" id=\"msg\"></div>\n  </div>\n\n  <div class=\"card\" style=\"padding:10px\">\n    <div id=\"stage\"><div class=\"blank-note\">字幕は非表示中です（<kbd>B</kbd> で再表示）</div></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>聞き取り中の文字 <small>確定前の認識結果</small></h2>\n    <div id=\"raw\">—</div>\n    <div class=\"row\" style=\"margin-top:10px\">\n      <input type=\"text\" id=\"manual\" placeholder=\"マイクなしで試す：文を入力して Enter（今の「話す人の言語」として翻訳）\" style=\"flex:1;min-width:240px\">\n      <button id=\"manualBtn\">表示</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>記録 <small>授業後に保存できます</small></h2>\n    <div class=\"row\" style=\"margin-bottom:8px\">\n      <button id=\"saveTxt\">テキストで保存</button>\n      <button id=\"saveCsv\">CSV（Excel用）で保存</button>\n      <button id=\"clearLog\">記録を消す</button>\n      <span class=\"hint\" id=\"logCount\"></span>\n    </div>\n    <div id=\"log\"></div>\n  </div>\n\n  <div class=\"card\" id=\"glossCard\">\n    <h2>授業の資料と用語集 <small>資料の言葉を優先して聞き取り・翻訳します</small></h2>\n    <div class=\"row\" style=\"margin-bottom:10px\">\n      <label>用語集 <select id=\"glossSel\"></select></label>\n      <button id=\"glossNew\">＋ 新しい用語集</button>\n      <button id=\"glossRename\">名前を変更</button>\n      <button id=\"glossDel\">削除</button>\n      <label style=\"margin-left:auto\"><input type=\"checkbox\" id=\"glossOn\" checked> この用語集を使う</label>\n    </div>\n    <div id=\"drop\" class=\"drop\">\n      <b>資料をここにドラッグ</b>（PowerPoint・PDF・Word・テキスト）<br>\n      <span class=\"hint\">または <button id=\"pickBtn\" type=\"button\">ファイルを選ぶ</button>\n      ・<button id=\"pasteBtn\" type=\"button\">文章を貼り付ける</button>　　講談の台本、授業のスライド、配布資料など。資料はこのパソコンの中だけで読み取ります。</span>\n      <input type=\"file\" id=\"fileIn\" multiple accept=\".pptx,.pdf,.docx,.txt,.md,.csv,.tsv\" hidden>\n    </div>\n    <div id=\"pasteBox\" style=\"display:none;margin-top:8px\">\n      <textarea id=\"pasteText\" rows=\"5\" placeholder=\"ここに文章を貼り付けて「読み取る」\"></textarea>\n      <div class=\"row\" style=\"margin-top:6px\"><button id=\"pasteGo\">読み取る</button><button id=\"pasteCancel\">閉じる</button></div>\n    </div>\n    <div class=\"msg\" id=\"glossMsg\"></div>\n    <div id=\"sources\" class=\"hint\"></div>\n\n    <div class=\"row\" style=\"margin:12px 0 6px\">\n      <button id=\"checkBtn\">まちがえて出やすい字をAIで調べる</button>\n      <button id=\"fillBtn\">空いている訳語を自動で入れる</button>\n      <button id=\"addRow\">＋ 1行追加</button>\n      <input type=\"text\" id=\"glossFilter\" placeholder=\"絞り込み\" style=\"width:120px\">\n      <span class=\"hint\" id=\"glossCount\"></span>\n      <span style=\"margin-left:auto\" class=\"row\">\n        <button id=\"glossExport\">書き出し</button>\n        <button id=\"glossImport\">読み込み</button>\n        <input type=\"file\" id=\"glossFile\" accept=\".tsv,.txt,.csv\" hidden>\n      </span>\n    </div>\n    <div class=\"howto\">\n      <b>この表のしくみ</b>　音声認識は、ときどき字をまちがえます。<br>\n      たとえば「<b>番所</b>」と言ったのに「<span class=\"bad\">番書</span>」と書いてしまう、など。<br>\n      この表があると、字幕に「<span class=\"bad\">番書</span>」が出そうになったとき、原稿の「<b>番所</b>」に<b>なおして</b>出します。<br>\n      <span class=\"small\">・「まちがえて出やすい字」はAIが考えた候補です。<b>おかしいものは × で消し</b>、足りないものは <b>＋</b> で足してください。<br>\n      ・「なおす」のチェックを外すと、その言葉はなおしません。　・読み方や英語・中国語がちがっていたら、そのまま書きかえられます。<br>\n      ・1文字の候補（例：「男」）は、ほかの意味でもよく使うので、なおす対象にしません。</span>\n    </div>\n    <div class=\"tablewrap\">\n      <table id=\"glossTable\">\n        <thead><tr>\n          <th title=\"この言葉を字幕で使う\">使う</th><th>原稿の言葉</th><th>読み方</th><th>英語では</th><th>中国語では</th>\n          <th title=\"チェックを外すと、この言葉はなおしません\">なおす</th><th>まちがえて出やすい字<br><span style=\"font-weight:400;font-size:11px\">これが出たら左の言葉になおします</span></th><th title=\"原稿に出てきた回数\">回数</th><th></th>\n        </tr></thead>\n        <tbody></tbody>\n      </table>\n    </div>\n    <details style=\"margin-top:10px\">\n      <summary>この仕組みについて</summary>\n      <div class=\"hint\" style=\"font-size:13px;margin-top:6px\">\n        <p><b>字のまちがいをなおす</b>：原稿を読み込むと、原稿に出てくる言葉だけをAIが調べ、「まちがえて出やすい字」を表に入れます。授業中にその字が出たら、原稿の言葉になおします。</p>\n        <p><b>翻訳の固定</b>：English・中文の欄に書いた訳語を、翻訳結果に必ず使います（英語・中国語で話したときも、その欄の言葉を手がかりに日本語の表記へ直します）。</p>\n        <p><b>注意</b>：「まちがえて出やすい字」に、ふだんよく使う言葉（例：「機関」の候補に「期間」）が入っていると、逆にまちがいが増えます。見つけたら × で消してください。なおしたところは、記録に「補正」として残ります。AIで調べるのは、原稿を読み込んだときと、ボタンを押したときだけです。</p>\n      </div>\n    </details>\n  </div>\n</section>\n\n<aside>\n  <div class=\"card\">\n    <h2>翻訳の準備 <small>授業の前に一度</small></h2>\n    <p class=\"hint\" style=\"margin:0 0 8px\">Chrome 内蔵の翻訳を使います（APIキー・料金なし）。初回は言語ごとのデータをダウンロードします。授業前にこのボタンを押しておくと本番がスムーズです。</p>\n    <button id=\"prepAll\">6方向の翻訳をすべて準備</button>\n    <div class=\"tr-status\" id=\"trStatus\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>表示の設定</h2>\n    <div class=\"grid2\">\n      <span>表示する言語</span>\n      <span class=\"row\">\n        <label><input type=\"checkbox\" id=\"show-ja\" checked> 日本語</label>\n        <label><input type=\"checkbox\" id=\"show-en\" checked> English</label>\n        <label><input type=\"checkbox\" id=\"show-zh\" checked> 中文</label>\n      </span>\n      <span>並び順</span>\n      <select id=\"order\">\n        <option value=\"src\">話した言語を一番上</option>\n        <option value=\"fixed\">いつも 日本語→English→中文</option>\n        <option value=\"srclast\">話した言語を一番下</option>\n      </select>\n      <span>文字の大きさ</span>\n      <span class=\"row\"><input type=\"range\" id=\"fontSize\" min=\"18\" max=\"90\" value=\"40\"><span id=\"fontVal\">40</span>px</span>\n      <span>表示する発言数</span>\n      <select id=\"rows\"><option>1</option><option selected>2</option><option>3</option><option>4</option><option>6</option></select>\n      <span>言語ラベル</span>\n      <label><input type=\"checkbox\" id=\"showTag\" checked> JA / EN / 中 を付ける</label>\n      <span>認識途中</span>\n      <label><input type=\"checkbox\" id=\"showInterim\" checked> 確定前の原文も薄く出す</label>\n      <span>背景</span>\n      <span class=\"colors\"><label>背景 <input type=\"color\" id=\"bg\" value=\"#000000\"></label></span>\n      <span>文字色</span>\n      <span class=\"colors\">\n        <label>日 <input type=\"color\" id=\"c-ja\" value=\"#ffffff\"></label>\n        <label>EN <input type=\"color\" id=\"c-en\" value=\"#ffe066\"></label>\n        <label>中 <input type=\"color\" id=\"c-zh\" value=\"#7fe3ff\"></label>\n      </span>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>辞書 <small>人名・専門用語の直し</small></h2>\n    <textarea id=\"dict\" rows=\"7\" spellcheck=\"false\"></textarea>\n    <p class=\"hint\" style=\"margin:6px 0 0\">1行に1つ。<b>まちがい → ただしい</b><br>\n    ・先頭に何も付けない行：聞き取った文字を直します（どの言語でも）<br>\n    ・<b>en:</b> <b>ja:</b> <b>zh:</b> を付けた行：その言語の訳文を直します</p>\n  </div>\n\n  <div class=\"card\">\n    <details>\n      <summary>細かい設定</summary>\n      <div class=\"grid2\" style=\"margin-top:10px\">\n        <span>区切る長さ</span>\n        <span><input type=\"number\" id=\"maxJa\" value=\"40\" min=\"15\" max=\"120\" style=\"width:64px\"> 字（日・中）</span>\n        <span></span>\n        <span><input type=\"number\" id=\"maxEn\" value=\"110\" min=\"40\" max=\"300\" style=\"width:64px\"> 文字（英語）</span>\n        <span>途切れ待ち</span>\n        <span><input type=\"number\" id=\"stall\" value=\"2.5\" min=\"1\" max=\"10\" step=\".5\" style=\"width:64px\"> 秒 認識が止まったら確定</span>\n        <span>用語ヒント</span>\n        <label><input type=\"checkbox\" id=\"localRec\"> 端末内の音声認識に用語を渡す（試験的・対応するChromeのみ）</label>\n      </div>\n      <p class=\"hint\">長く話し続けても字幕が出ないときは「区切る長さ」を短くしてください。</p>\n    </details>\n  </div>\n\n  <div class=\"card\">\n    <details>\n      <summary>使い方と注意</summary>\n      <div class=\"hint\" style=\"font-size:13px;margin-top:8px\">\n      <p>① PC版 Chrome で開きます（https://kyokudominamifuji.com/subtitles/class/ 、またはパソコン内の「起動.cmd」から）。<br>\n      ② 「6方向の翻訳をすべて準備」を押して、すべて「使えます」になるのを待ちます。<br>\n      ③ 話す人の言語を選び「マイク開始」。話し手が変わったら <kbd>1</kbd> 日本語 / <kbd>2</kbd> English / <kbd>3</kbd> 中文 で切り替えます。<br>\n      ④ 「プロジェクター用の画面」を押し、出てきた窓をプロジェクター側へ移して、窓の中をクリックすると全画面になります。</p>\n      <p>キー：<kbd>M</kbd> マイク開始/停止、<kbd>B</kbd> 字幕を消す、<kbd>F</kbd> 全画面、<kbd>C</kbd> 画面クリア（入力欄の編集中は無効）。</p>\n      <p>注意：音声認識は自動で言語を判別できないため、話す人が変わったら言語ボタンで切り替えてください。音声認識はChromeが音声をGoogleのサーバーへ送って処理する場合があり、インターネット接続が必要です。翻訳は端末内で行われます。機械翻訳なので、誤訳や認識ミスがあり得ます。</p>\n      <p>中文は台湾の繁体字（zh-TW）で聞き取り・表示します。</p>\n      </div>\n    </details>\n  </div>\n</aside>\n</main>\n\n<script>\n'use strict';\n/* =========================================================\n   用語集エンジン（資料の言葉を優先する仕組み）\n   rows: [{on,ja,yomi,en,zh,homo,n}]\n   ========================================================= */\nconst Gloss=(()=>{\n  const kata=s=>String(s||'').replace(/[ぁ-ゖ]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));\n  const hira=s=>String(s||'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));\n  const yomiKey=s=>kata(String(s||'').normalize('NFKC').replace(/[\\s・･]/g,''));\n  const reEsc=s=>s.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&');\n  // 英語の照合：大文字小文字・長音記号（ō, ū など）・ハイフンの違いを無視\n  const VAR={a:'aāâáà',e:'eēêéè',i:'iīîíì',o:'oōôóò',u:'uūûúù'};\n  const enPat=w=>[...w.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')].map(c=>{const l=c.toLowerCase();return VAR[l]?'['+VAR[l]+VAR[l].toUpperCase()+']':/[\\s\\-]/.test(c)?'[\\\\s\\\\-]?':reEsc(c);}).join('');\n  const enRe=w=>new RegExp('(^|[^\\\\p{L}\\\\p{N}])('+enPat(w)+')(?=$|[^\\\\p{L}\\\\p{N}])','giu');\n  const isKana=s=>/^[ぁ-ゖァ-ヺー]+$/.test(s);\n  const active=rows=>(rows||[]).filter(r=>r&&r.on);\n\n  /* ---- 日本語：原稿の用語の「聞き間違い」を用語の表記に直す（辞書なし） ----\n     r.alts = ['公団','講壇'] のような、その用語だけの聞き間違い候補（AIが調べ、人が直せる） */\n  function correctJa(text,rows){\n    const fixes=[],saved=[];\n    const act=active(rows).filter(r=>r.ja);\n    const known=new Set(act.map(r=>r.ja));\n    const protect=(w)=>{saved.push(w);return '\\uE000'+(saved.length-1)+'\\uE001';};\n    // 1) 正しい表記はそのまま守る（長い用語から）\n    for(const r of [...act].sort((a,b)=>b.ja.length-a.ja.length))if(text.includes(r.ja))text=text.split(r.ja).join(protect(r.ja));\n    // 2) 聞き間違い候補を置き換える（長い候補から）\n    const pairs=[];\n    for(const r of act)if(r.homo)for(const a of (r.alts||[]))if(a&&[...a].length>=2&&a!==r.ja&&!known.has(a))pairs.push([a,r.ja]);\n    pairs.sort((x,y)=>y[0].length-x[0].length);\n    for(const [a,to] of pairs){\n      if(!text.includes(a))continue;\n      // かなだけの候補は、前後もかなだと単語の一部の可能性があるので直さない\n      if(isKana(a)){\n        const re=new RegExp('(^|[^\\u3041-\\u30ffー])'+reEsc(a)+'(?=$|[^\\u3041-\\u30ffー])','g');\n        text=text.replace(re,(m,p1)=>{fixes.push({from:a,to});return p1+protect(to);});\n      }else{\n        const n=text.split(a).length-1;for(let i=0;i<n;i++)fixes.push({from:a,to});\n        text=text.split(a).join(protect(to));\n      }\n    }\n    // 3) 読みがかなのまま聞き取られた場合（カタカナの単語ぴったり）\n    for(const r of act.filter(r=>r.homo&&yomiKey(r.yomi).length>=3)){\n      const y=yomiKey(r.yomi);\n      const re=new RegExp('(^|[^ァ-ヺー])'+reEsc(y)+'(?=$|[^ァ-ヺー])','g');\n      text=text.replace(re,(m,p1)=>{fixes.push({from:y,to:r.ja});return p1+protect(r.ja);});\n    }\n    text=text.replace(/\\uE000(\\d+)\\uE001/g,(m,i)=>saved[i]);\n    return {text,fixes};\n  }\n  /* ---- 英語：用語の大文字・つづりをそろえる ---- */\n  function correctEn(text,rows){\n    const fixes=[],saved=[];\n    for(const r of active(rows).filter(r=>r.en).sort((a,b)=>b.en.length-a.en.length)){\n      text=text.replace(enRe(r.en),(m,p,w)=>{if(w!==r.en)fixes.push({from:w,to:r.en});saved.push(r.en);return p+'\\uE000'+(saved.length-1)+'\\uE001';});\n    }\n    text=text.replace(/\\uE000(\\d+)\\uE001/g,(m,i)=>saved[i]);\n    return {text,fixes};\n  }\n  function correct(text,lang,rows){\n    if(lang==='ja')return correctJa(text,rows);\n    if(lang==='en')return correctEn(text,rows);\n    return {text,fixes:[]};\n  }\n  /* ---- 音声認識の候補のうち、用語を多く含むものを選ぶ ---- */\n  function score(text,lang,rows){\n    let s=0;const low=text.toLowerCase();\n    for(const r of active(rows)){const w=r[lang];if(!w||w.length<2)continue;\n      if(lang==='en'?enRe(w).test(text):low.includes(w.toLowerCase()))s+=w.length;}\n    return s;\n  }\n  function pickAlternative(alts,lang,rows){\n    if(!alts.length)return 0;\n    const base=score(alts[0],lang,rows);let best=0,bs=base;\n    alts.forEach((a,i)=>{const v=score(a,lang,rows);if(v>bs){bs=v;best=i;}});\n    return best;\n  }\n  /* ---- 翻訳：用語集の訳語を必ず使う ---- */\n  const plainCache=new Map();\n  function findAll(text,word,lang){\n    if(lang==='en')return enRe(word);\n    return null;\n  }\n  async function translate(text,src,tgt,rows,tr){\n    if(src===tgt)return text;\n    const withTgt=active(rows).filter(r=>r[src]&&r[tgt]);\n    // 訳語のない長い用語の中に、訳語のある短い用語が含まれる場合は、長い用語を丸ごと守る\n    const lc=x=>x.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();\n    const terms=active(rows).filter(r=>r[src]&&(r[tgt]||withTgt.some(o=>o!==r&&o[src].length<r[src].length&&lc(r[src]).includes(lc(o[src])))))\n      .sort((a,b)=>b[src].length-a[src].length);\n    let s=text;const hits=[];\n    for(const r of terms){\n      const token='ZXQ'+hits.length+'QXZ';let count=0;\n      if(src==='en'){const re=findAll(s,r.en,'en');s=s.replace(re,(m,p)=>{count++;return p+token;});}\n      else if(s.includes(r[src])){count=s.split(r[src]).length-1;s=s.split(r[src]).join(token);}\n      if(count)hits.push({token,count,from:r[src],to:r[tgt]||r[src]});\n    }\n    if(!hits.length)return await tr(text,src,tgt);\n    try{\n      let out=await tr(s,src,tgt),ok=true;\n      for(const h of hits){\n        const re=new RegExp(h.token.replace(/(\\d+)/,'\\\\s*$1\\\\s*'),'gi');\n        const n=(out.match(re)||[]).length;if(n!==h.count){ok=false;break;}\n        out=out.replace(re,()=>h.to);\n      }\n      if(ok&&!/ZXQ|QXZ/i.test(out))return out;\n    }catch(e){}\n    // 目印が崩れたときは、普通に訳してから用語の訳を差し替える\n    let plain=await tr(text,src,tgt);\n    for(const h of hits){\n      const key=src+'>'+tgt+':'+h.from;\n      try{\n        if(!plainCache.has(key))plainCache.set(key,(await tr(h.from,src,tgt)).replace(/[。.．]$/,'').trim());\n        const t0=plainCache.get(key);\n        if(t0&&t0!==h.to){\n          if(tgt==='en')plain=plain.replace(new RegExp(reEsc(t0),'gi'),h.to);else plain=plain.split(t0).join(h.to);\n        }\n      }catch(e){}\n    }\n    return plain;\n  }\n  /* ---- 資料から用語を拾う ---- */\n  const EN_STOP=new Set('The This That These Those There Then When Where What Which Who Why How In On At For From With And But Or If As By To Of A An It Its We Our You Your They Their He She His Her I My Me Is Are Was Were Be Not No Yes Please Thank Thanks Today Also Figure Fig Table Page Chapter Section Slide Note Example Q A Mr Ms Dr'.split(' '));\n  const HAN='\\\\p{Script=Han}々〆',KAT='\\\\p{Script=Katakana}ー';\n  function extract(text){\n    text=String(text||'').normalize('NFKC');\n    const found=new Map();\n    const add=(o,boost=0)=>{\n      const key=(o.ja||o.en||o.zh||'').toLowerCase();if(!key)return;\n      const e=found.get(key)||{ja:'',yomi:'',en:'',zh:'',n:0,pattern:false};\n      for(const f of ['ja','yomi','en','zh'])if(o[f]&&!e[f])e[f]=o[f];\n      e.n+=o.count||1;if(boost)e.pattern=true;found.set(key,e);\n    };\n    const kanaRatio=(text.match(/[ぁ-ヿ]/g)||[]).length/Math.max(1,(text.match(/[\\p{Script=Han}ぁ-ヿ]/gu)||[]).length);\n    const zhDoc=kanaRatio<0.08&&/\\p{Script=Han}/u.test(text);\n    // 1) 対訳・読みの書き方：講談（Kodan）／Kodan（講談）／講談（こうだん）／タブ区切り\n    for(const m of text.matchAll(new RegExp(`([${HAN}${KAT}]{2,20})\\\\s*[(]\\\\s*([A-Za-z][A-Za-z0-9 .'’\\\\-]{1,40}?)\\\\s*[)]`,'gu')))\n      add({[zhDoc?'zh':'ja']:m[1],en:m[2].trim()},1);\n    for(const m of text.matchAll(new RegExp(`([A-Z][A-Za-z0-9 .'’\\\\-]{1,40}?)\\\\s*[(]\\\\s*([${HAN}${KAT}]{2,20})\\\\s*[)]`,'gu')))\n      add({[zhDoc?'zh':'ja']:m[2],en:m[1].trim()},1);\n    for(const m of text.matchAll(new RegExp(`([${HAN}]{1,12})\\\\s*[(《]\\\\s*([\\\\p{Script=Hiragana}ー]{2,30})\\\\s*[)》]`,'gu')))\n      add({ja:m[1],yomi:m[2]},1);\n    for(const line of text.split(/\\r?\\n/)){\n      const c=line.split('\\t').map(x=>x.trim());\n      if(c.length>=2&&c[0].length<=20&&c[1].length<=50&&/[\\p{Script=Han}ぁ-ヿ]/u.test(c[0])&&/^[A-Za-z]/.test(c[1]))\n        add({ja:c[0],en:c[1],zh:c[2]&&/\\p{Script=Han}/u.test(c[2])?c[2]:''},1);\n    }\n    // 読みの書き方を取り除いてから候補を拾う\n    const body=text.replace(/[(《][\\p{Script=Hiragana}ー]{2,30}[)》]/gu,'');\n    // 2) 日本語・中国語の用語候補\n    {\n      for(const m of body.matchAll(new RegExp(`[${HAN}${KAT}]{2,16}`,'gu'))){\n        const s=m[0];if(/^ー/.test(s))continue;\n        add(zhDoc?{zh:s}:{ja:s});\n      }\n    }\n    // 3) 英語の固有名詞・略語\n    for(const m of body.matchAll(/\\b(?:[A-Z][a-zA-Z’'\\-]+|[A-Z]{2,}[a-z]?)(?:\\s+(?:of|the|and|de|von|du)\\s+[A-Z][a-zA-Z’'\\-]+|\\s+(?:[A-Z][a-zA-Z’'\\-]+|[A-Z]{2,}))*\\b/g)){\n      let s=m[0].trim();const words=s.split(/\\s+/);\n      while(words.length&&EN_STOP.has(words[0]))words.shift();\n      s=words.join(' ');if(s.length<3||EN_STOP.has(s))continue;\n      if(words.length===1&&s.length<4&&!/^[A-Z]{2,}$/.test(s))continue;\n      add({en:s});\n    }\n    // 「伊賀越」と「伊賀越え」のような、ほぼ同じ候補を1つにまとめる\n    const all=[...found.values()];\n    return all.filter(e=>!e.ja||e.pattern||!all.some(f=>f!==e&&f.ja&&f.ja!==e.ja&&f.ja.startsWith(e.ja)&&(f.n>=e.n||(f.pattern&&f.ja.length-e.ja.length<=2))));\n  }\n  /* ---- 用語集に合流させる ---- */\n  function merge(rows,list){\n    const idx=new Map();rows.forEach(r=>{for(const f of ['ja','en','zh'])if(r[f])idx.set(f+':'+r[f].toLowerCase(),r);});\n    let added=0;\n    for(const e of list){\n      const r=(e.ja&&idx.get('ja:'+e.ja.toLowerCase()))||(e.en&&idx.get('en:'+e.en.toLowerCase()))||(e.zh&&idx.get('zh:'+e.zh.toLowerCase()));\n      if(r){r.n=(r.n||0)+e.n;for(const f of ['ja','yomi','en','zh'])if(e[f]&&!r[f])r[f]=e[f];continue;}\n      const nr={on:e.pattern||e.n>=2,ja:e.ja,yomi:e.yomi?hira(e.yomi):'',en:e.en,zh:e.zh,\n        homo:false,alts:[],n:e.n};\n      rows.push(nr);added++;for(const f of ['ja','en','zh'])if(nr[f])idx.set(f+':'+nr[f].toLowerCase(),nr);\n    }\n    rows.sort((a,b)=>(b.on-a.on)||((b.n||0)-(a.n||0)));\n    return added;\n  }\n  return {kata,hira,yomiKey,correct,correctJa,correctEn,score,pickAlternative,translate,extract,merge};\n})();\n\n/* =========================================================\n   資料の読み取り（PowerPoint / Word / PDF / テキスト）\n   ========================================================= */\nconst Sources=(()=>{\n  async function unzip(buf){\n    const dv=new DataView(buf);let eocd=-1;\n    for(let i=buf.byteLength-22;i>=Math.max(0,buf.byteLength-65557);i--)if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}\n    if(eocd<0)throw new Error('ファイルが壊れているか、対応していない形式です');\n    const n=dv.getUint16(eocd+10,true);let p=dv.getUint32(eocd+16,true);const files={};\n    for(let k=0;k<n;k++){\n      const method=dv.getUint16(p+10,true),csize=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lho=dv.getUint32(p+42,true);\n      const name=new TextDecoder().decode(new Uint8Array(buf,p+46,nl));files[name]={method,csize,lho};p+=46+nl+el+cl;\n    }\n    return {names:Object.keys(files),async read(name){\n      const f=files[name];if(!f)return '';\n      const start=f.lho+30+dv.getUint16(f.lho+26,true)+dv.getUint16(f.lho+28,true);\n      const data=new Uint8Array(buf,start,f.csize);\n      if(f.method===0)return new TextDecoder().decode(data);\n      const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));\n      return await new Response(stream).text();\n    }};\n  }\n  const xml=s=>new DOMParser().parseFromString(s,'application/xml');\n  function paragraphs(doc,pTag,tTag){\n    const out=[];\n    for(const p of doc.getElementsByTagName(pTag)){\n      let s='';\n      const walk=node=>{for(const c of node.childNodes){\n        if(c.nodeType!==1)continue;\n        if(c.nodeName==='w:ruby'){ // Wordのふりがな → 漢字（よみ）\n          const base=[...c.getElementsByTagName('w:rubyBase')].map(b=>[...b.getElementsByTagName('w:t')].map(t=>t.textContent).join('')).join('');\n          const rt=[...c.getElementsByTagName('w:rt')].map(b=>[...b.getElementsByTagName('w:t')].map(t=>t.textContent).join('')).join('');\n          s+=rt?base+'（'+rt+'）':base;continue;\n        }\n        if(c.nodeName===tTag)s+=c.textContent;\n        else if(c.nodeName==='w:tab'||c.nodeName==='a:tab')s+='\\t';\n        else if(c.nodeName===pTag)continue;\n        else walk(c);\n      }};\n      walk(p);if(s.trim())out.push(s);\n    }\n    return out.join('\\n');\n  }\n  async function pptx(buf){\n    const z=await unzip(buf),num=n=>Number((n.match(/(\\d+)\\.xml$/)||[])[1]||0);\n    const slides=z.names.filter(n=>/^ppt\\/slides\\/slide\\d+\\.xml$/.test(n)).sort((a,b)=>num(a)-num(b));\n    const notes=z.names.filter(n=>/^ppt\\/notesSlides\\/notesSlide\\d+\\.xml$/.test(n)).sort((a,b)=>num(a)-num(b));\n    const parts=[];\n    for(const n of slides)parts.push(paragraphs(xml(await z.read(n)),'a:p','a:t'));\n    for(const n of notes)parts.push(paragraphs(xml(await z.read(n)),'a:p','a:t'));\n    return parts.join('\\n');\n  }\n  async function docx(buf){\n    const z=await unzip(buf);\n    return paragraphs(xml(await z.read('word/document.xml')),'w:p','w:t');\n  }\n  const PDFJS='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.2.108/build/';\n  let pdfLib=null;\n  async function pdf(buf){\n    if(!pdfLib){pdfLib=await import(PDFJS+'pdf.min.mjs');pdfLib.GlobalWorkerOptions.workerSrc=PDFJS+'pdf.worker.min.mjs';}\n    const doc=await pdfLib.getDocument({data:new Uint8Array(buf),cMapUrl:PDFJS.replace('build/','cmaps/'),cMapPacked:true}).promise;\n    const out=[];\n    for(let i=1;i<=doc.numPages;i++){\n      const tc=await (await doc.getPage(i)).getTextContent();\n      out.push(tc.items.map(it=>it.str+(it.hasEOL?'\\n':'')).join(''));\n    }\n    return out.join('\\n');\n  }\n  async function read(file){\n    const ext=(file.name.match(/\\.([^.]+)$/)||[])[1]?.toLowerCase()||'';\n    if(ext==='pptx')return pptx(await file.arrayBuffer());\n    if(ext==='docx')return docx(await file.arrayBuffer());\n    if(ext==='pdf')return pdf(await file.arrayBuffer());\n    if(['ppt','doc'].includes(ext))throw new Error('古い形式（.'+ext+'）です。PowerPoint / Word で「名前を付けて保存」→ .'+ext+'x 形式にしてから入れてください');\n    return await file.text();\n  }\n  return {read,unzip,pptx,docx,pdf,PDFJS};\n})();\n\n</script>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nconst LANGS={\n  ja:{label:'日本語',tag:'JA',rec:'ja-JP',tr:'ja',html:'ja'},\n  en:{label:'English',tag:'EN',rec:'en-US',tr:'en',html:'en'},\n  zh:{label:'中文',tag:'中',rec:'zh-TW',tr:'zh-Hant',html:'zh-Hant-TW'}\n};\nconst KEYS=['ja','en','zh'];\nconst store={get(k,d){try{const v=localStorage.getItem('classSubs.'+k);return v==null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem('classSubs.'+k,JSON.stringify(v));}catch(e){}}};\n\nconst state={\n  speaker:store.get('speaker','ja'),\n  running:false,rec:null,session:0,\n  committed:new Map(),interims:[],\n  rows:store.get('rows.log',[]),hideBefore:0,\n  interimText:'',blank:false,popup:null,\n  translators:new Map(),trInfo:{},\n  chain:Promise.resolve()\n};\n\n/* ---------- 設定 ---------- */\nconst settingIds=['show-ja','show-en','show-zh','order','fontSize','rows','showTag','showInterim','bg','c-ja','c-en','c-zh','dict','maxJa','maxEn','stall','localRec'];\nconst DEFAULT_DICT=`# 例（# で始まる行は無視されます）\n# 金井先生 → 釜井先生\n# en: Mr. Kanai → Mr. Kamai\n# zh: 金井 → 釜井`;\nfunction loadSettings(){\n  const s=store.get('settings',{});\n  for(const id of settingIds){const el=$(id);if(!(id in s)){if(id==='dict')el.value=DEFAULT_DICT;continue;}\n    if(el.type==='checkbox')el.checked=s[id];else el.value=s[id];}\n}\nfunction saveSettings(){\n  const s={};for(const id of settingIds){const el=$(id);s[id]=el.type==='checkbox'?el.checked:el.value;}\n  store.set('settings',s);\n}\nconst setting=id=>{const el=$(id);return el.type==='checkbox'?el.checked:el.value;};\n\n/* ---------- 辞書 ---------- */\nfunction parseDict(){\n  const src=[],out={ja:[],en:[],zh:[]};\n  for(let line of $('dict').value.split(/\\r?\\n/)){\n    line=line.trim();if(!line||line.startsWith('#'))continue;\n    let target=null;const m=line.match(/^(ja|en|zh)\\s*[:：]\\s*(.*)$/i);\n    if(m){target=m[1].toLowerCase();line=m[2];}\n    const parts=line.split(/\\s*(?:→|->|=>|⇒|\\t)\\s*/);\n    if(parts.length<2||!parts[0])continue;\n    const rule=[parts[0],parts.slice(1).join(' ')];\n    (target?out[target]:src).push(rule);\n  }\n  return {src,out};\n}\nfunction applyRules(text,rules,lang){\n  for(const [a,b] of rules){\n    if(lang==='en'&&/^[\\w .'-]+$/.test(a)){\n      const re=new RegExp('\\\\b'+a.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')+'\\\\b','gi');text=text.replace(re,b);\n    }else text=text.split(a).join(b);\n  }\n  return text;\n}\n\n/* ---------- 翻訳（Chrome 内蔵 Translator API） ---------- */\nconst hasTranslator=()=>'Translator' in self;\nfunction pairKey(a,b){return a+'>'+b;}\nasync function ensureTranslator(a,b,{gesture=false}={}){\n  const key=pairKey(a,b);\n  if(state.translators.has(key))return state.translators.get(key);\n  if(!hasTranslator()){setTr(key,'ng','このブラウザは内蔵翻訳に未対応');return null;}\n  const opts={sourceLanguage:LANGS[a].tr,targetLanguage:LANGS[b].tr};\n  let avail;\n  try{avail=await Translator.availability(opts);}catch(e){avail='unavailable';}\n  if(avail==='unavailable'){setTr(key,'ok','英語経由で翻訳します');return null;}\n  if(avail!=='available'&&!gesture){setTr(key,'dl','未準備（「準備」ボタンを押してください）');return null;}\n  try{\n    setTr(key,'dl',avail==='available'?'読み込み中…':'ダウンロード中…');\n    const t=await Translator.create({...opts,monitor(m){m.addEventListener('downloadprogress',e=>setTr(key,'dl','ダウンロード中 '+Math.round(e.loaded*100)+'%'));}});\n    state.translators.set(key,t);setTr(key,'ok','使えます');return t;\n  }catch(e){setTr(key,'ng','準備できません：'+(e.message||e.name));return null;}\n}\nfunction setTr(key,cls,text){state.trInfo[key]={cls,text};renderTr();}\nfunction renderTr(){\n  const box=$('trStatus');box.replaceChildren();\n  for(const a of KEYS)for(const b of KEYS){if(a===b)continue;const key=pairKey(a,b),i=state.trInfo[key];\n    const l=document.createElement('span');l.textContent=LANGS[a].label+' → '+LANGS[b].label;\n    const r=document.createElement('span');r.textContent=i?i.text:'未確認';r.className=i?i.cls:'';box.append(l,r);}\n}\nasync function prepareFrom(src,gesture){\n  // 話し手の言語から他の2言語へ。直接できない組は英語経由にするので、英語との組も準備\n  const jobs=[];\n  for(const b of KEYS)if(b!==src)jobs.push(ensureTranslator(src,b,{gesture}));\n  const res=await Promise.all(jobs);\n  if(src!=='en'){\n    const other=KEYS.find(k=>k!==src&&k!=='en');\n    if(!state.translators.has(pairKey(src,other))){await ensureTranslator(src,'en',{gesture});await ensureTranslator('en',other,{gesture});}\n  }\n  return res;\n}\nfunction withTimeout(p,ms){return Promise.race([p,new Promise((_,rej)=>setTimeout(()=>rej(new Error('時間切れ')),ms))]);}\nasync function localTranslate(text,a,b){\n  const key=pairKey(a,b);\n  const t=state.translators.get(key)||await ensureTranslator(a,b);\n  if(!t)return null;\n  try{return await withTimeout(t.translate(text),10000);}\n  catch(e){\n    // 内蔵翻訳がエラーになったら、作り直して1回だけやり直す\n    state.translators.delete(key);try{t.destroy&&t.destroy();}catch(_){}\n    const t2=await ensureTranslator(a,b);\n    if(!t2)throw e;\n    return await withTimeout(t2.translate(text),10000);\n  }\n}\nasync function serverTranslate(text,a,b){\n  const glossary=glossActive()?glossRows().filter(r=>r.on).slice(0,80).map(r=>({ja:r.ja||'',en:r.en||'',zh:r.zh||'',yomi:r.yomi||''})):[];\n  const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),20000);\n  try{\n    const r=await fetch(API_BASE+'/subtitles/api/translate',{method:'POST',headers:{'content-type':'application/json'},signal:ctl.signal,body:JSON.stringify({text,src:a,targets:[b],glossary})});\n    const d=await r.json();\n    if(!r.ok||!d[b])throw new Error('サーバー翻訳：'+(d.error||r.status));\n    return d[b];\n  }finally{clearTimeout(timer);}\n}\nasync function translate(text,a,b){\n  if(a===b)return text;\n  let err=null;\n  try{\n    const out=await localTranslate(text,a,b);\n    if(out!=null)return out;\n    if(a!=='en'&&b!=='en'){ // 英語経由\n      const mid=await translate(text,a,'en');\n      return await translate(mid,'en',b);\n    }\n    err=new Error('翻訳が準備されていません');\n  }catch(e){err=e;}\n  // 内蔵翻訳がうまくいかないときは、サイトのサーバーで翻訳（https のページのみ）\n  if(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'){\n    try{const out=await serverTranslate(text,a,b);setTr(pairKey(a,b),'dl','内蔵翻訳でエラー → サーバーで翻訳中');return out;}\n    catch(e2){err=new Error((err&&err.message||'')+' / '+e2.message);}\n  }\n  throw err;\n}\n\n/* ---------- 字幕の行 ---------- */\nlet rowSeq=state.rows.reduce((m,r)=>Math.max(m,r.id||0),0);\nfunction addUtterance(rawText,src){\n  const dict=parseDict();\n  let text=rawText.trim(),fixes=[];\n  if(glossActive()){const g=Gloss.correct(text,src,glossRows());text=g.text;fixes=g.fixes;}\n  text=applyRules(text,dict.src,src);\n  if(!text)return;\n  const row={id:++rowSeq,time:new Date().toISOString(),src,text:{[src]:text},err:{},fixes};\n  state.rows.push(row);if(state.rows.length>2000)state.rows.shift();\n  render();renderLog();\n  state.chain=state.chain.then(()=>translateRow(row,dict)).catch(()=>{});\n}\nasync function translateRow(row,dict){\n  // 同時に頼むと内蔵翻訳がぶつかることがあるので、1言語ずつ順番に訳す\n  for(const k of orderFor(row.src).filter(k=>k!==row.src)){\n    try{\n      const out=glossActive()?await Gloss.translate(row.text[row.src],row.src,k,glossRows(),translate):await translate(row.text[row.src],row.src,k);\n      row.text[k]=applyRules(out,dict.out[k],k);delete row.err[k];\n    }\n    catch(e){row.err[k]=(e&&(e.name&&e.name!=='Error'?e.name+'：':'')+(e.message||e))||'不明なエラー';}\n    render();\n  }\n  store.set('rows.log',state.rows.slice(-500));\n  render();renderLog();\n}\n\n/* ---------- 描画 ---------- */\nfunction orderFor(src){\n  const o=setting('order');\n  if(o==='fixed')return KEYS;\n  const rest=KEYS.filter(k=>k!==src);\n  return o==='src'?[src,...rest]:[...rest,src];\n}\nfunction esc(s){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));}\nfunction stageHTML(){\n  const n=Number(setting('rows')),tag=setting('showTag');\n  const rows=state.rows.filter(r=>r.id>(state.hideBefore||0)).slice(-n);\n  let h='';\n  rows.forEach((r,idx)=>{\n    h+=`<div class=\"sub-row${idx<rows.length-1&&!state.interimText?' old':''}\">`;\n    for(const k of orderFor(r.src)){\n      if(!setting('show-'+k))continue;\n      const txt=r.text[k];\n      let body,cls='';\n      if(txt)body=esc(txt);else if(r.err[k]){continue;}else{body='…';cls=' wait';}\n      h+=`<div class=\"sub-line${cls}\" lang=\"${LANGS[k].html}\" style=\"color:${setting('c-'+k)}\">${tag?`<span class=\"tag\">${LANGS[k].tag}</span>`:''}<span>${body}</span></div>`;\n    }\n    h+='</div>';\n  });\n  if(state.interimText&&setting('showInterim')&&setting('show-'+state.speaker)){\n    const k=state.speaker;\n    h+=`<div class=\"sub-row\"><div class=\"sub-line interim\" lang=\"${LANGS[k].html}\" style=\"color:${setting('c-'+k)}\">${tag?`<span class=\"tag\">${LANGS[k].tag}</span>`:''}<span>${esc(state.interimText)}</span></div></div>`;\n  }\n  return h;\n}\nfunction render(){\n  const html=stageHTML(),fs=setting('fontSize')+'px',bg=setting('bg');\n  const stage=$('stage');\n  stage.querySelectorAll('.sub-row').forEach(e=>e.remove());\n  stage.insertAdjacentHTML('beforeend',html);\n  stage.style.fontSize=(stage.matches(':fullscreen')?fs:Math.min(Number(setting('fontSize')),34)+'px');\n  stage.style.background=bg;stage.classList.toggle('blank',state.blank);\n  const p=state.popup;\n  if(p&&!p.closed){try{const s=p.document.getElementById('s');s.innerHTML=state.blank?'':html;s.style.fontSize=fs;p.document.body.style.background=bg;}catch(e){}}\n}\nfunction renderLog(){\n  const box=$('log'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<30;\n  box.replaceChildren();\n  for(const r of state.rows.slice(-200)){\n    const d=document.createElement('div');d.className='item';\n    const t=document.createElement('div');t.className='t';t.textContent=new Date(r.time).toLocaleTimeString('ja-JP')+'　話した言語：'+LANGS[r.src].label;d.append(t);\n    for(const k of [r.src,...KEYS.filter(x=>x!==r.src)]){const l=document.createElement('div');l.lang=LANGS[k].html;l.textContent=LANGS[k].tag+'　'+(r.text[k]||(r.err[k]?'（翻訳できませんでした：'+r.err[k]+'）':'…'));d.append(l);}\n    if(r.fixes&&r.fixes.length){const f=document.createElement('div');f.className='fix';f.textContent='補正：'+r.fixes.map(x=>x.from+' → '+x.to).join('、');d.append(f);}\n    box.append(d);\n  }\n  $('logCount').textContent=state.rows.length+'件';\n  if(atBottom)box.scrollTop=box.scrollHeight;\n}\n\n/* ---------- 音声認識 ---------- */\nconst SR=window.SpeechRecognition||window.webkitSpeechRecognition;\nfunction status(text,on){$('statusText').textContent=text;$('dot').classList.toggle('on',!!on);}\nfunction msg(t){$('msg').textContent=t||'';}\nfunction maxLen(lang){return Number(lang==='en'?setting('maxEn'):setting('maxJa'))||40;}\nfunction cutPoint(text,max,lang){\n  const slice=text.slice(0,max);\n  const re=lang==='en'?/[.!?;,](?=\\s)|\\s/g:/[。！？!?、，,；]/g;\n  let cut=0,m;while((m=re.exec(slice)))cut=m.index+m[0].length;\n  return cut>=max*0.4?cut:max;\n}\nfunction commit(text){if(text&&text.trim())addUtterance(text,state.speaker);}\n\nfunction startRec(){\n  const r=new SR(),session=++state.session;\n  state.rec=r;state.committed=new Map();state.interims=[];\n  r.lang=LANGS[state.speaker].rec;r.continuous=true;r.interimResults=true;r.maxAlternatives=glossActive()?5:1;\n  state.usingLocal=false;\n  if(setting('localRec')&&!state.noLocal&&glossActive()&&'processLocally' in r&&window.SpeechRecognitionPhrase){\n    const words=[...new Set(glossRows().filter(x=>x.on).map(x=>x[state.speaker]).filter(w=>w&&w.length>=2))].slice(0,500);\n    if(words.length){try{r.processLocally=true;r.phrases=words.map(w=>new SpeechRecognitionPhrase(w,3.0));state.usingLocal=true;}catch(e){r.processLocally=false;}}\n  }\n  r.onstart=()=>{if(session===state.session)status('聞き取り中：'+LANGS[state.speaker].label+(state.usingLocal?'（端末内・用語ヒントあり）':''),true);};\n  r.onresult=e=>{\n    if(session!==state.session)return;\n    const now=performance.now(),interims=[];let shown='';\n    for(let i=e.resultIndex;i<e.results.length;i++){\n      const res=e.results[i],txt=res[0].transcript;let c=state.committed.get(i)||0;\n      if(c>txt.length)c=txt.length;\n      if(res.isFinal){\n        let use=txt;\n        if(c===0&&res.length>1&&glossActive()){\n          const alts=[...res].map(a=>a.transcript);const k=Gloss.pickAlternative(alts,state.speaker,glossRows());\n          if(k>0)use=alts[k];\n        }\n        commit(use.slice(c));state.committed.set(i,txt.length);continue;\n      }\n      let rest=txt.slice(c);const max=maxLen(state.speaker);\n      while(rest.length>max){const cut=cutPoint(rest,max,state.speaker);commit(rest.slice(0,cut));c+=cut;state.committed.set(i,c);rest=rest.slice(cut);}\n      const prev=state.interims.find(x=>x.i===i);\n      interims.push({i,base:c,text:rest,at:prev&&prev.text===rest&&prev.base===c?prev.at:now});\n      shown+=rest;\n    }\n    state.interims=interims;state.interimText=shown.trim();\n    $('raw').textContent=state.interimText||'—';render();\n  };\n  r.onerror=e=>{\n    if(session!==state.session)return;\n    if(state.usingLocal&&['phrases-not-supported','language-not-supported','service-not-allowed'].includes(e.error)){\n      state.noLocal=true;msg('この環境では端末内の音声認識（用語ヒント）が使えないため、通常の音声認識で続けます。用語集による補正・翻訳の固定は有効です。');return;\n    }\n    if(e.error==='not-allowed'||e.error==='service-not-allowed'){msg('マイクが許可されていません。アドレスバー左のアイコンからマイクを「許可」にしてください。Windowsの設定 → プライバシー → マイク も確認してください。');stopAll();}\n    else if(e.error==='network')msg('音声認識の通信に失敗しました。インターネット接続を確認してください。自動で再接続します。');\n    else if(e.error==='language-not-supported'){msg('この言語の音声認識に対応していません：'+LANGS[state.speaker].label);stopAll();}\n    else if(e.error!=='no-speech'&&e.error!=='aborted')msg('音声認識エラー：'+e.error);\n  };\n  r.onend=()=>{\n    if(session!==state.session)return;\n    flushInterims();\n    if(state.running)setTimeout(()=>{if(state.running&&session===state.session){try{startRec();}catch(e){msg('再開できませんでした：'+e.message);}}},250);\n  };\n  r.start();\n}\nfunction flushInterims(){\n  for(const x of state.interims){commit(x.text);state.committed.set(x.i,x.base+x.text.length);}\n  state.interims=[];state.interimText='';$('raw').textContent='—';\n}\nsetInterval(()=>{ // 認識が止まったまま確定しないときに確定させる\n  if(!state.running||!state.interims.length)return;\n  const now=performance.now(),limit=Number(setting('stall'))*1000;\n  let changed=false;\n  for(const x of state.interims)if(x.text&&now-x.at>limit){commit(x.text);state.committed.set(x.i,x.base+x.text.length);x.base+=x.text.length;x.text='';changed=true;}\n  if(changed){state.interims=state.interims.filter(x=>x.text);state.interimText=state.interims.map(x=>x.text).join('').trim();$('raw').textContent=state.interimText||'—';render();}\n},300);\n\nasync function startAll(){\n  if(state.running)return;\n  if(!SR){msg('このブラウザは音声認識に未対応です。パソコン版の Google Chrome で開いてください。');return;}\n  if(!isSecureContext){msg('マイクを使うには https://kyokudominamifuji.com/subtitles/class/ か「起動.cmd」から開いてください（ファイルを直接開くとマイクが使えません）。');return;}\n  msg('');\n  if(!hasTranslator())msg('このブラウザでは内蔵翻訳が使えません（Chrome 138以降のパソコン版が必要です）。話した言語の字幕だけを表示します。');\n  status('翻訳を準備中…');\n  await prepareFrom(state.speaker,true);\n  await prepareLocal(state.speaker);\n  state.running=true;$('micBtn').textContent='■ 停止';$('micBtn').classList.add('stop');\n  try{startRec();}catch(e){msg('開始できませんでした：'+e.message);stopAll();}\n}\nfunction stopAll(){\n  state.running=false;state.session++;\n  if(state.rec){try{state.rec.stop();}catch(e){}}\n  flushInterims();state.rec=null;\n  $('micBtn').textContent='🎤 マイク開始';$('micBtn').classList.remove('stop');status('停止中');render();\n}\nasync function setSpeaker(lang){\n  if(!LANGS[lang])return;\n  const was=state.running;\n  if(was){state.session++;if(state.rec){try{state.rec.abort();}catch(e){}}flushInterims();}\n  state.speaker=lang;store.set('speaker',lang);\n  document.querySelectorAll('#speakers button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));\n  prepareFrom(lang,true);\n  if(was){try{startRec();}catch(e){msg('切り替えできませんでした：'+e.message);}}\n  render();\n}\n\n/* ---------- プロジェクター画面 ---------- */\nfunction openProjector(){\n  const p=window.open('','class-subtitles-screen','popup,width=1200,height=700');\n  if(!p){msg('ポップアップがブロックされました。アドレスバー右のアイコンから許可するか、「全画面」を使ってください。');return;}\n  state.popup=p;\n  p.document.open();\n  p.document.write(`<!doctype html><html><head><meta charset=\"utf-8\"><title>字幕（クリックで全画面）</title><style>\n  html,body{margin:0;height:100%;background:#000;color:#fff;font-family:\"Yu Gothic UI\",\"Hiragino Sans\",\"Noto Sans JP\",\"Microsoft JhengHei\",sans-serif;cursor:pointer;overflow:hidden}\n  #s{position:absolute;inset:0;padding:4vh 5vw;display:flex;flex-direction:column;justify-content:flex-end}\n  .sub-row{margin-top:.55em}.sub-row.old{opacity:.55}\n  .sub-line{display:flex;gap:.45em;align-items:baseline;line-height:1.3;word-break:break-word}\n  .sub-line .tag{font-size:.42em;border:1px solid currentColor;border-radius:.3em;padding:0 .35em;opacity:.75;flex:none;transform:translateY(-.25em);font-weight:700}\n  .sub-line.wait{opacity:.45}.sub-line.interim{opacity:.55}\n  </style></head><body><div id=\"s\"></div></body></html>`);\n  p.document.close();\n  p.document.body.addEventListener('click',()=>{const d=p.document;if(!d.fullscreenElement)d.documentElement.requestFullscreen().catch(()=>{});});\n  p.addEventListener('keydown',onKey);\n  render();\n}\n\n/* ---------- 保存 ---------- */\nfunction download(name,text,type){\n  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();\n  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000);\n}\nfunction stamp(){const d=new Date(),z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}${z(d.getMonth()+1)}${z(d.getDate())}_${z(d.getHours())}${z(d.getMinutes())}`;}\n$('saveTxt').onclick=()=>{\n  const t=state.rows.map(r=>`[${new Date(r.time).toLocaleTimeString('ja-JP')}] ${LANGS[r.src].label}\\n`+[r.src,...KEYS.filter(k=>k!==r.src)].map(k=>`  ${LANGS[k].tag}: ${r.text[k]||''}`).join('\\n')).join('\\n\\n');\n  download('授業字幕_'+stamp()+'.txt','\\ufeff'+t,'text/plain');\n};\n$('saveCsv').onclick=()=>{\n  const q=s=>'\"'+String(s||'').replace(/\"/g,'\"\"')+'\"';\n  const lines=[['時刻','話した言語','日本語','English','中文'].map(q).join(',')];\n  for(const r of state.rows)lines.push([new Date(r.time).toLocaleString('ja-JP'),LANGS[r.src].label,r.text.ja,r.text.en,r.text.zh].map(q).join(','));\n  download('授業字幕_'+stamp()+'.csv','\\ufeff'+lines.join('\\r\\n'),'text/csv');\n};\n$('clearLog').onclick=()=>{if(!confirm('記録をすべて消しますか？（先に保存をおすすめします）'))return;state.rows=[];store.set('rows.log',[]);render();renderLog();};\n\n/* ---------- 操作 ---------- */\ndocument.querySelectorAll('#speakers button').forEach(b=>b.onclick=()=>setSpeaker(b.dataset.lang));\n$('micBtn').onclick=()=>state.running?stopAll():startAll();\n$('projBtn').onclick=openProjector;\n$('fsBtn').onclick=()=>{const s=$('stage');if(document.fullscreenElement)document.exitFullscreen();else s.requestFullscreen().then(render).catch(()=>{});};\ndocument.addEventListener('fullscreenchange',render);\n$('blankBtn').onclick=()=>{state.blank=!state.blank;$('blankBtn').firstChild.textContent=state.blank?'字幕を表示 ':'字幕を消す ';render();};\n$('clearBtn').onclick=()=>{state.hideBefore=rowSeq;render();}; // 画面だけ消す（記録は残る）\n$('prepAll').onclick=async()=>{\n  if(!hasTranslator()){msg('このブラウザでは内蔵翻訳が使えません。パソコン版 Chrome（138以降）で開いてください。');renderTr();return;}\n  $('prepAll').disabled=true;\n  for(const a of KEYS)for(const b of KEYS)if(a!==b)await ensureTranslator(a,b,{gesture:true});\n  $('prepAll').disabled=false;\n};\n$('manual').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();$('manualBtn').click();}});\n$('manualBtn').onclick=async()=>{const v=$('manual').value;if(!v.trim())return;await prepareFrom(state.speaker,true);addUtterance(v,state.speaker);$('manual').value='';};\nfunction onKey(e){\n  const t=e.target;if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT'))return;\n  if(e.ctrlKey||e.metaKey||e.altKey)return;\n  const k=e.key.toLowerCase();\n  if(k==='1')setSpeaker('ja');else if(k==='2')setSpeaker('en');else if(k==='3')setSpeaker('zh');\n  else if(k==='m')$('micBtn').click();else if(k==='b')$('blankBtn').click();\n  else if(k==='f')$('fsBtn').click();else if(k==='c')$('clearBtn').click();\n  else return;\n  e.preventDefault();\n}\ndocument.addEventListener('keydown',onKey);\nfor(const id of settingIds)$(id).addEventListener(id==='dict'?'input':'input',()=>{saveSettings();if(id==='fontSize')$('fontVal').textContent=$('fontSize').value;render();});\nfor(const id of settingIds)$(id).addEventListener('change',()=>{saveSettings();render();});\nwindow.addEventListener('beforeunload',()=>{if(state.popup&&!state.popup.closed)state.popup.close();});\n\n/* ---------- 端末内の音声認識（用語ヒント）の準備 ---------- */\nasync function prepareLocal(lang){\n  if(!setting('localRec')||state.noLocal||!glossActive()||!SR||typeof SR.available!=='function')return;\n  const opt={langs:[LANGS[lang].rec],processLocally:true};\n  try{\n    const a=await SR.available(opt);\n    if(a==='unavailable'){state.noLocal=true;msg('この言語は端末内の音声認識に未対応のため、通常の音声認識を使います（用語集による補正・翻訳の固定は有効です）。');return;}\n    if(a!=='available'&&typeof SR.install==='function'){status('端末内の音声認識を準備中…');await SR.install(opt);}\n  }catch(e){state.noLocal=true;}\n}\n\n/* =========================================================\n   用語集の管理\n   ========================================================= */\nconst G=store.get('glossaries',null)||{cur:'授業',sets:{'授業':{on:true,rows:[],sources:[]}}};\nif(!G.sets[G.cur])G.cur=Object.keys(G.sets)[0];\nconst curSet=()=>G.sets[G.cur];\nfunction glossRows(){return curSet()?curSet().rows:[];}\nfunction glossActive(){const c=curSet();return !!(c&&c.on!==false&&c.rows.some(r=>r.on));}\nlet saveTimer=0;\nfunction saveGloss(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>store.set('glossaries',G),300);renderChip();}\nfunction gmsg(t){$('glossMsg').textContent=t||'';}\nfunction renderChip(){\n  const c=curSet(),n=c?c.rows.filter(r=>r.on).length:0;\n  $('glossChip').textContent=c&&c.on!==false&&n?`用語集：${G.cur}（${n}語）`:'用語集：未使用';\n}\nfunction renderGlossSel(){\n  const sel=$('glossSel');sel.replaceChildren();\n  for(const name of Object.keys(G.sets)){const o=document.createElement('option');o.value=o.textContent=name;sel.append(o);}\n  sel.value=G.cur;$('glossOn').checked=curSet().on!==false;\n  renderSources();renderGlossTable();renderChip();\n}\nfunction renderSources(){\n  const s=curSet().sources||[];\n  $('sources').textContent=s.length?'読み込んだ資料：'+s.map(x=>x.name).join('、'):'';\n}\nconst COLS=[['ja','原稿の言葉'],['yomi',''],['en',''],['zh','']];\nfunction renderGlossTable(){\n  const tb=$('glossTable').tBodies[0],q=$('glossFilter').value.trim().toLowerCase(),rows=glossRows();\n  tb.replaceChildren();let shown=0;\n  rows.forEach((r,i)=>{\n    if(q&&!COLS.some(([f])=>(r[f]||'').toLowerCase().includes(q)))return;\n    if(++shown>600)return;\n    const tr=document.createElement('tr');tr.classList.toggle('off',!r.on);\n    const cb=(f,title)=>{const td=document.createElement('td');td.style.textAlign='center';const c=document.createElement('input');c.type='checkbox';c.checked=!!r[f];c.title=title;\n      c.onchange=()=>{r[f]=c.checked;if(f==='homo'&&c.checked&&!(r.alts&&r.alts.length))gmsg('「まちがえて出やすい字」が空です。＋で足すか「まちがえて出やすい字をAIで調べる」を押してください。');if(f==='homo'&&c.checked&&r.ja&&!r.on){r.on=true;}tr.classList.toggle('off',!r.on);saveGloss();};\n      td.append(c);return td;};\n    tr.append(cb('on','この用語を使う'));\n    for(const [f,ph] of COLS){const td=document.createElement('td');const inp=document.createElement('input');inp.type='text';inp.value=r[f]||'';inp.placeholder=ph;\n      if(f==='yomi')inp.lang='ja';if(f==='zh')inp.lang='zh-Hant-TW';\n      inp.oninput=()=>{r[f]=inp.value.trim();saveGloss();};td.append(inp);tr.append(td);}\n    tr.append(cb('homo','チェックを外すと、この言葉はなおしません'));\n    {const td=document.createElement('td');const box=document.createElement('div');box.className='chips';\n     const draw=()=>{box.replaceChildren();\n       for(const a of (r.alts||[])){\n         const c=document.createElement('span');c.className='chip'+([...a].length<2?' off':'');c.textContent=a;\n         if([...a].length<2)c.title='1文字なので、なおす対象にしません';\n         const x=document.createElement('button');x.textContent='×';x.title='「'+a+'」を消す';\n         x.onclick=()=>{r.alts=r.alts.filter(v=>v!==a);saveGloss();draw();renderCount();};c.append(x);box.append(c);\n       }\n       const add=document.createElement('button');add.className='add';add.textContent='＋';add.title='まちがえて出やすい字を足す';\n       add.onclick=()=>{const v=(prompt('「'+(r.ja||'この言葉')+'」と言ったとき、まちがえて出やすい字を入れてください（例：公団）')||'').trim();\n         if(!v)return;r.alts=[...new Set([...(r.alts||[]),...v.split(/[、,，\\s]+/).filter(Boolean)])].filter(a=>a!==r.ja);if(r.ja&&!r.homo){r.homo=true;}saveGloss();renderGlossTable();};\n       box.append(add);};\n     draw();td.append(box);tr.append(td);}\n    const n=document.createElement('td');n.className='n';n.textContent=r.n||'';tr.append(n);\n    const del=document.createElement('td');const b=document.createElement('button');b.textContent='✕';b.title='この行を削除';\n    b.onclick=()=>{rows.splice(i,1);saveGloss();renderGlossTable();};del.append(b);tr.append(del);\n    tb.append(tr);\n  });\n  renderCount(shown);\n}\nfunction renderCount(shown){\n  const rows=glossRows(),on=rows.filter(r=>r.on).length,homo=rows.filter(r=>r.on&&r.homo&&(r.alts||[]).some(a=>[...a].length>=2)).length;\n  $('glossCount').textContent=`${rows.length}語（使う ${on}・なおす ${homo}）`+(shown>600?' ※表示は600行まで。絞り込みを使ってください':'');\n}\nasync function addSourceText(name,text){\n  if(!text||!text.trim()){gmsg(name+'：文字を読み取れませんでした（画像だけの資料は読み取れません）。');return;}\n  const list=Gloss.extract(text);\n  const added=Gloss.merge(curSet().rows,list);\n  (curSet().sources=curSet().sources||[]).push({name,chars:text.length,at:new Date().toISOString()});\n  saveGloss();renderSources();renderGlossTable();\n  gmsg(`${name}：${text.length.toLocaleString()}文字を読み取り、用語を${added}件追加しました。`);\n  // この原稿の用語だけ、聞き間違いをAIで調べる\n  await checkHomophones(text.slice(0,1500));\n}\nconst API_BASE=location.hostname.endsWith('kyokudominamifuji.com')?'':'https://kyokudominamifuji.com';\nasync function checkHomophones(context,all){\n  const HAN=/[\\p{Script=Han}]/u;\n  const targets=glossRows().filter(r=>r.on&&r.ja&&HAN.test(r.ja)&&r.ja.length<=12&&(all||!r.checked)).slice(0,150);\n  if(!targets.length){gmsg($('glossMsg').textContent+'\\n調べる用語はありません。');return;}\n  const btn=$('checkBtn');btn.disabled=true;const base=$('glossMsg').textContent;\n  let done=0,found=0,failed='';\n  for(let i=0;i<targets.length;i+=30){\n    const batch=targets.slice(i,i+30);\n    gmsg(`${base}\\nまちがえて出やすい字をAIで調べています… ${done}/${targets.length}語`);\n    try{\n      const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),90000);\n      const r=await fetch(API_BASE+'/subtitles/api/homophones',{method:'POST',headers:{'content-type':'application/json'},signal:ctl.signal,\n        body:JSON.stringify({terms:batch.map(x=>({ja:x.ja,yomi:x.yomi||''})),context:context||''})}).finally(()=>clearTimeout(timer));\n      const d=await r.json();if(!r.ok)throw new Error(d.error||r.status);\n      for(const it of d.items||[]){\n        const row=batch.find(x=>x.ja===it.ja);if(!row)continue;\n        if(it.yomi&&!row.yomi)row.yomi=it.yomi;\n        const alts=[...new Set([...(row.alts||[]),...(it.confusions||[])])].filter(a=>a&&a!==row.ja);\n        row.alts=alts;row.checked=true;\n        if(alts.length&&!it.risky){row.homo=true;found++;}\n      }\n    }catch(e){failed=e.name==='AbortError'?'時間切れ':(e.message||String(e));break;}\n    done+=batch.length;saveGloss();renderGlossTable();\n  }\n  btn.disabled=false;\n  gmsg(base+(failed?`\\nAIのチェックが途中で止まりました（${failed}）。「まちがえて出やすい字をAIで調べる」でやり直せます。`\n    :`\\n${done}語をAIで調べ、${found}語に候補を入れました。表の「まちがえて出やすい字」を見て、おかしいものは × で消してください。`));\n}\nasync function handleFiles(files){\n  for(const f of files){\n    gmsg(f.name+' を読み取り中…');\n    try{await addSourceText(f.name,await Sources.read(f));}\n    catch(e){gmsg(f.name+'：読み取れませんでした。'+(e.message||e));}\n  }\n}\n$('pickBtn').onclick=()=>$('fileIn').click();\n$('fileIn').onchange=e=>{handleFiles([...e.target.files]);e.target.value='';};\nconst drop=$('drop');\ndrop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over');});\ndrop.addEventListener('dragleave',()=>drop.classList.remove('over'));\ndrop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');handleFiles([...e.dataTransfer.files]);});\n$('pasteBtn').onclick=()=>{$('pasteBox').style.display='block';$('pasteText').focus();};\n$('pasteCancel').onclick=()=>{$('pasteBox').style.display='none';};\n$('pasteGo').onclick=async()=>{const t=$('pasteText').value;if(!t.trim())return;await addSourceText('貼り付けた文章',t);$('pasteText').value='';$('pasteBox').style.display='none';};\n$('glossSel').onchange=()=>{G.cur=$('glossSel').value;saveGloss();renderGlossSel();};\n$('glossOn').onchange=()=>{curSet().on=$('glossOn').checked;saveGloss();};\n$('glossNew').onclick=()=>{\n  const name=(prompt('新しい用語集の名前（例：講談、日本文化論、第3回）')||'').trim();if(!name)return;\n  if(G.sets[name]){alert('同じ名前があります');return;}\n  G.sets[name]={on:true,rows:[],sources:[]};G.cur=name;saveGloss();renderGlossSel();\n};\n$('glossRename').onclick=()=>{\n  const name=(prompt('新しい名前',G.cur)||'').trim();if(!name||name===G.cur)return;\n  if(G.sets[name]){alert('同じ名前があります');return;}\n  G.sets[name]=G.sets[G.cur];delete G.sets[G.cur];G.cur=name;saveGloss();renderGlossSel();\n};\n$('glossDel').onclick=()=>{\n  if(!confirm(`用語集「${G.cur}」を削除しますか？（先に「書き出し」で保存をおすすめします）`))return;\n  delete G.sets[G.cur];if(!Object.keys(G.sets).length)G.sets['授業']={on:true,rows:[],sources:[]};\n  G.cur=Object.keys(G.sets)[0];saveGloss();renderGlossSel();\n};\n$('addRow').onclick=()=>{glossRows().unshift({on:true,ja:'',yomi:'',en:'',zh:'',homo:false,n:0});$('glossFilter').value='';saveGloss();renderGlossTable();$('glossTable').tBodies[0].querySelector('input[type=text]')?.focus();};\n$('glossFilter').oninput=renderGlossTable;\n$('checkBtn').onclick=()=>{const src=(curSet().sources||[]).length;gmsg('');checkHomophones('',true);};\n$('fillBtn').onclick=async()=>{\n  if(!hasTranslator()){gmsg('このブラウザでは内蔵翻訳が使えません。');return;}\n  $('fillBtn').disabled=true;\n  const rows=glossRows().filter(r=>r.on);let n=0,i=0;\n  for(const src of KEYS)if(rows.some(r=>r[src]))await prepareFrom(src,true);\n  for(const r of rows){\n    i++;if(i%5===0)gmsg(`訳語を入れています… ${i}/${rows.length}`);\n    const src=r.ja?'ja':r.en?'en':r.zh?'zh':null;if(!src)continue;\n    for(const k of KEYS)if(k!==src&&!r[k]){try{r[k]=(await translate(r[src],src,k)).replace(/[。.．]$/,'').trim();n++;}catch(e){}}\n  }\n  saveGloss();renderGlossTable();$('fillBtn').disabled=false;\n  gmsg(`${n}か所に機械翻訳の訳語を入れました。授業で使う訳語に合わせて直してください（ここに書いた訳語が字幕で必ず使われます）。`);\n};\n$('glossExport').onclick=()=>{\n  const lines=['使う\\t日本語\\tよみ\\tEnglish\\t中文\\t直す\\t聞き間違い'];\n  for(const r of glossRows())lines.push([r.on?1:0,r.ja,r.yomi,r.en,r.zh,r.homo?1:0,(r.alts||[]).join('、')].map(x=>String(x??'').replace(/[\\t\\r\\n]/g,' ')).join('\\t'));\n  download('用語集_'+G.cur+'.tsv','﻿'+lines.join('\\r\\n'),'text/tab-separated-values');\n};\n$('glossImport').onclick=()=>$('glossFile').click();\n$('glossFile').onchange=async e=>{\n  const f=e.target.files[0];e.target.value='';if(!f)return;\n  const text=(await f.text()).replace(/^﻿/,'');const rows=[];\n  for(const line of text.split(/\\r?\\n/)){\n    const c=line.split(line.includes('\\t')?'\\t':',').map(x=>x.trim().replace(/^\"|\"$/g,''));\n    if(!line.trim()||c[1]==='日本語')continue;\n    if(/^[01]$/.test(c[0])&&c.length>=5)rows.push({on:c[0]==='1',ja:c[1],yomi:c[2],en:c[3],zh:c[4],homo:c[5]==='1',alts:(c[6]||'').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),n:0});\n    else rows.push({on:true,ja:c[0]||'',yomi:'',en:c[1]||'',zh:c[2]||'',homo:false,n:0});\n  }\n  const before=glossRows().length;\n  for(const r of rows){const ex=glossRows().find(x=>(r.ja&&x.ja===r.ja)||(!r.ja&&r.en&&x.en===r.en));if(ex)Object.assign(ex,Object.fromEntries(Object.entries(r).filter(([k,v])=>v!==''&&k!=='n')));else glossRows().push(r);}\n  saveGloss();renderGlossTable();gmsg(`${rows.length}行を読み込みました（新規 ${glossRows().length-before}行）。`);\n};\n\n/* ---------- 初期化 ---------- */\nrenderGlossSel();\nstate.hideBefore=rowSeq; // 前回の授業の字幕は画面に出さない（記録には残る）\nloadSettings();$('fontVal').textContent=$('fontSize').value;\ndocument.querySelectorAll('#speakers button').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.speaker));\nrenderTr();render();renderLog();\nif(!SR)msg('このブラウザは音声認識に未対応です。パソコン版の Google Chrome で開いてください。');\nelse if(!isSecureContext)msg('今はファイルを直接開いているため、マイクが使えません。同じフォルダーの「起動.cmd」をダブルクリックして開いてください。（文字入力での試しはこのままできます）');\nelse if(!hasTranslator())msg('このブラウザでは内蔵翻訳が使えません（Chrome 138以降のパソコン版が必要です）。');\n</script>\n</body>\n</html>\n";
